param([int]$Batch=1,[switch]$Baseline,[string]$Case='')
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..")
$out="$repo/build-extractors/runtime-test/second-ten-ten-20261112/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";[void][IO.Directory]::CreateDirectory($out)
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 $mode=if($Baseline){'baseline'}else{'fixed'}
 $prepare=if($Batch -eq 1){'prepare_second_ten_ten_20261112.py'}elseif($Batch -eq 2){'prepare_second_ten_ten_20261112_second.py'}elseif($Batch -eq 3){'prepare_second_ten_ten_20261112_third.py'}elseif($Batch -eq 4){'prepare_second_ten_ten_20261112_fourth.py'}elseif($Batch -eq 5){'prepare_second_ten_ten_20261112_fifth.py'}elseif($Batch -eq 6){'prepare_second_ten_ten_20261112_sixth.py'}elseif($Batch -eq 7){'prepare_second_ten_ten_20261112_seventh.py'}elseif($Batch -eq 8){'prepare_second_ten_ten_20261112_eighth.py'}elseif($Batch -eq 9){'prepare_second_ten_ten_20261112_ninth.py'}else{throw 'Unimplemented batch'}
 & C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe "$PSScriptRoot/$prepare" $out $mode
 if($LASTEXITCODE){throw 'Extraction failed'}
 $keys=@(Get-Content "$out/cases.json" -Raw|ConvertFrom-Json);$indices=if($Case){$index=[Array]::IndexOf($keys,$Case);if($index -lt 0){throw 'Unknown case'};@($index)}else{@(0..9)}
 $failures=@('Ordinary forfeit applies health penalty','Actual wild GUID is released exactly once','Repeated finish cannot replay XP or callbacks','A temporary swap lock cannot cancel earned experience','All crossed native thresholds trigger their level side effects','MoveType zero must reach its leave switch arm','Equal-weight ordering must be irreflexive','A fresh proposal requires fresh answers from both sides','Replacing a pending request must release its earlier allocation','Admission must measure the actual two participants')
 if($Batch -eq 2){$failures=@('An unrelated player cannot cancel another duel request','A dead challenged player is rejected','A webbed forfeiter cannot flee an unwebbed opponent','A dead active pet cannot admit ordinary abilities','Native type-restricted other allies receive12 once and caster is untouched','Marked target supplies the native bonus and damage is calculated once','Aquatic pet reduces native periodic fungus damage by half','Use-based ramping still advances on a miss','Native removal expires the named aura only on its actual target','Native weather bonus is included before division across three enemies')}
 if($Batch -eq 3){$failures=@('Clicking the same owned companion dismisses it without resummoning','Repeated APPLY retains the requested favorite flag','A locked combat slot cannot accept a journal pet','An empty recipient roster cannot pacify either duel participant','A native ability lock retains its separate lock duration and ordinary cooldown','A saved zero-health journal pet must remain dead on admission','Unchanged saved experience must not be reported as a new award','Large queue sample counts retain the native weighted mean without32bit overflow','Journal removal dismisses the matching companion and clears combat references','A name query cannot bind another journal pet to the current creature')}
 if($Batch -eq 6){$failures=@('Tail Sweep must execute its first-strike native18-point branch','Native signed speed removal must subtract1000 through unbounded zero limits','Refreshing three remaining rounds must preserve phase3 and extend actual expiry to5','Unsigned native65535 duration must become the real infinite sentinel','Sunlight must scale native maximum health and retain40percent current health','A personal native block charge must prevent one hit and expire without negative state','Refuge must shield its user and the eligible living critter ally exactly once','Native Wish50percent cannot gain another caster-power multiplier','A canceled aura cannot send a fresh buff-change or continue its periodic phase','Two live native aura instances must have distinct protocol identities')}
 if($Batch -eq 7){$failures=@('Charged rocket must survive the round before its second activation','Stockpile modifiers must survive until the reserve is consumed','Plant must retain its nutrient controller between activations','A two-charge native wall must survive the round boundary','A conditional extra hit must not execute without its required target state','A ten-percent native hit cannot gain another caster-power multiplier','Consume Corpse heals its user by fifty percent and consumes an unused allied corpse once','A native priority removal must recover speed even when its current value exceeds the upper bound','Vengeance must not multiply recorded incoming damage by caster power again','A pet duel cannot admit the same player as both participants')}
 if($Batch -eq 8){$failures=@('Evolved zealot must dispatch all four authored combat timers','Blazing construct must execute its first authored Fiery Slash','Janalai hatchling must dispatch its authored Flame Buffet','Stone Quilen must dispatch and repeat all three native attacks','Horde captain must dispatch its first Counter Shot','Black Harvest felhunter must dispatch its authored first dispel','Pummel must repeat its own event after the first interrupt','Gyrokill Shadow Power must repeat under its own event','Nature Guardian must preserve the actual wide healing input','Vanished caster access violation')}
 if($Batch -eq 9){$failures=@('Gogduh reset must discard its previous owned combat events','Magmolatus reset must discard the previous combat phase callback','Roltall reset must discard its previous boulder continuation','Felmyst reset must discard its previous flight continuation','Fiery Vortex reset must discard an old tornado callback','Living Meteor reset must discard its old thaw continuation','Flarecore reset must discard its previous expiry deadline','Royal sentinel reset must discard its previous attack queue','Unga Knife Fight must repeat under its own event','Nefarian Shadowblaze must repeat under its own event')}
 $testSource=if($Batch -eq 1){'SecondTenTen20261112FirstTest.cpp'}elseif($Batch -eq 2){'SecondTenTen20261112SecondTest.cpp'}elseif($Batch -eq 3){'SecondTenTen20261112ThirdTest.cpp'}elseif($Batch -eq 4){'SecondTenTen20261112FourthTest.cpp'}elseif($Batch -eq 5){'SecondTenTen20261112FifthTest.cpp'}elseif($Batch -eq 6){'SecondTenTen20261112SixthTest.cpp'}elseif($Batch -eq 7){'SecondTenTen20261112SeventhTest.cpp'}elseif($Batch -eq 8){'SecondTenTen20261112EighthTest.cpp'}else{'SecondTenTen20261112NinthTest.cpp'}
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 [IO.File]::WriteAllText("$out/build.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncl /nologo /EHsc /std:c++17 /W4 /MD /fsanitize=address /Zi /I`"$out`" `"$PSScriptRoot/$testSource`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`" /Fd`"$out/compiler.pdb`"`nexit /b %errorlevel%`n")
 & cmd.exe /d /c "`"$out/build.cmd`" > `"$out/build.log`" 2>&1";if($LASTEXITCODE){Get-Content "$out/build.log" -Tail 18;throw 'Fixture compilation failed'}
 if($Batch -eq 7){
  $command=Get-Content "$out/build.cmd" -Raw;$command=$command.Replace('SecondTenTen20261112SeventhTest.cpp','SecondTenTen20261112SeventhAdmission.cpp').Replace('test.exe','admission.exe').Replace('test.obj','admission.obj');[IO.File]::WriteAllText("$out/build-admission.cmd",$command)
  & cmd.exe /d /c "`"$out/build-admission.cmd`" > `"$out/build-admission.log`" 2>&1";if($LASTEXITCODE){Get-Content "$out/build-admission.log" -Tail 15;throw 'Admission fixture compilation failed'}
 }
 foreach($index in $indices){
  [IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`n`"$out/test.exe`" $index`nexit /b %errorlevel%`n")
  if($Batch -eq 7 -and $index -eq 9){$run=Get-Content "$out/run.cmd" -Raw;[IO.File]::WriteAllText("$out/run.cmd",$run.Replace('test.exe','admission.exe'))}
  & cmd.exe /d /c "`"$out/run.cmd`" > `"$out/run-$index.log`" 2>&1";$code=$LASTEXITCODE;$raw=Get-Content "$out/run-$index.log" -Raw
  if($Baseline -and $Batch -eq 8 -and $index -eq 9){if(!$code -or !$raw.Contains('AddressSanitizer: access-violation')){Get-Content "$out/run-$index.log" -Tail 10;throw 'Missing vanished-caster counterfactual'};'PASS expected-broken pinned vanished-caster ASAN access violation;paired fixed required'}
  elseif($Baseline -and ($Batch -eq 4 -or ($Batch -eq 5 -and $index -lt 9))){if(!$code -or !$raw.Contains('AddressSanitizer: heap-use-after-free')){Get-Content "$out/run-$index.log" -Tail 10;throw "Expected source lifetime counterfactual missing:$($keys[$index])"};"PASS expected-broken pinned heap-use-after-free:$($keys[$index]);paired repaired run required"}
  elseif($Baseline -and $Batch -eq 5){if($code -ne 1 -or !$raw.Contains('Missing first ally type cannot block another eligible injured ally')){throw 'Expected healer target-selection counterfactual missing'};'PASS expected-broken pinned healer target selection; paired fixed required'}
  elseif($Baseline){if($code -ne 1 -or $raw.Trim() -cne $failures[$index]){throw "Expected pinned assertion missing:$($keys[$index])"};"PASS expected-broken pinned counterfactual:$($keys[$index]);paired repaired run required"}
  elseif($code -or !$raw.Contains('PASS complete production')){Get-Content "$out/run-$index.log" -Tail 18;throw "Regression failed:$($keys[$index])"}else{"$($keys[$index]):$($raw.Trim())"}
 }
}
$global:LASTEXITCODE=0
